CREATE TABLE IF NOT EXISTS organization_policies(org uuid NOT NULL REFERENCES organizations,version integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),demo boolean NOT NULL DEFAULT true,cancel_hours integer NOT NULL CHECK(cancel_hours>=0),PRIMARY KEY(org,version));
CREATE TABLE IF NOT EXISTS cancellation_events(id uuid NOT NULL,org uuid NOT NULL,booking_id uuid NOT NULL,policy_version integer NOT NULL,late boolean NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org,id),UNIQUE(org,booking_id),FOREIGN KEY(org,booking_id) REFERENCES bookings(org,id),FOREIGN KEY(org,policy_version) REFERENCES organization_policies(org,version));
